// Perfil / Títulos: the title packets the lobby entry pushes (2363 + 2383), the get / equip / release handlers
// (2376 / 2378 / 2380, = C# PROTOCOL_BASE_USER_TITLE_*) and the client's copy of the rules (src/lobby/core/titleLogic.ts,
// titleData.ts generated by tools/export-titles.mjs). The handler tests write through the real pool: the fake accounts have no
// rows, so every UPDATE is a no-op, and the titles used have no award items (no inserts); they skip without a database.
//   node --test test/titles.test.ts
import { test, after } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { PacketReader, PacketWriter } from "../../src/net/packet.ts";
import { parseMedalInfo, parseTitleInfo } from "../../src/net/titleClient.ts";
import { TITLES, TREE_NODES } from "../../src/lobby/core/titleData.ts";
import { emptyTitleState, equipBlock, getBlock, hasTitle, type TitleState } from "../../src/lobby/core/titleLogic.ts";
import { pool } from "../src/db.ts";
import { handleTitleChange, handleTitleEquip, handleTitleRelease, loadProfileData, titleInfoPackets, titlesTable } from "../src/game/profileHandlers.ts";
import { PlayerTitles } from "../src/shared/models.ts";
import type { GameClient } from "../src/game/gameServer.ts";
import type { Account } from "../src/shared/account.ts";
import { fakeAccount, opOf, u32, type Sent } from "./fakeRoom.ts";

after(async () => { await pool.end(); });

type Badges = { ribbon: number; ensign: number; medal: number; masterMedal: number };
function player(pid: number, sent: Sent[], o: Partial<Badges> & { rank?: number } = {}) {
  const a = Object.assign(fakeAccount(pid, `T${pid}`, sent, { rank: o.rank ?? 1 }), {
    ribbon: o.ribbon ?? 0, ensign: o.ensign ?? 0, medal: o.medal ?? 0, masterMedal: o.masterMedal ?? 0,
    title: new PlayerTitles(), equipment: { beretItem: 0 },
  });
  const c = { player: a, session: { send: (b: Uint8Array) => sent.push({ to: a.playerId, op: opOf(b), bytes: b }) } } as unknown as GameClient;
  return { a: a as unknown as Account & { title: PlayerTitles }, c };
}
const req = (...bytes: number[]) => { const w = new PacketWriter(); for (const b of bytes) w.writeC(b); return new PacketReader(w.toBytes(), 0); };
const last = (sent: Sent[], op: number) => sent.filter((s) => s.op === op).at(-1);

async function db(t: { skip(m: string): void }): Promise<boolean> {
  try { await loadProfileData(); } catch { t.skip("no database"); return false; }
  if (titlesTable().size === 0) { t.skip("no system_titles rows"); return false; }
  return true;
}

// ---- data ------------------------------------------------------------------------------------------------------------

test("titleData: 44 titles, wire ids 1..44, tree buttons are a permutation of them", () => {
  assert.equal(TITLES.length, 44);
  TITLES.forEach((t, i) => assert.equal(t.id, i + 1));
  assert.deepEqual([...TREE_NODES].sort((a, b) => a - b), TITLES.map((t) => t.id));
  assert.deepEqual(TREE_NODES.slice(0, 7), [1, 2, 3, 4, 5, 6, 7], "the first seven nodes are the common chain and the three heads");
});

test("titleData requirements = the system_titles seed (db/init/001_init.sql)", () => {
  const sql = readFileSync(new URL("../../db/init/001_init.sql", import.meta.url), "utf8");
  const start = sql.indexOf("COPY public.system_titles ");
  const block = sql.slice(start, sql.indexOf("\\.\n", start));
  const rows = block.split("\n").slice(1).filter((l) => /^\d/.test(l)).map((l) => l.split("\t").map(Number));
  assert.equal(rows.length, 44);
  for (const [id, classId, ribbon, ensign, medal, master, rank, slot, req1, req2] of rows) {
    assert.deepEqual(TITLES[id - 1], { ...TITLES[id - 1], id, classId, ribbon, ensign, medal, master, rank, slot, req1, req2 });
  }
});

test("titleData requirements = the live system_titles table (needs the DB)", async (t) => {
  if (!(await db(t))) return;
  for (const d of TITLES) {
    const m = titlesTable().get(d.id);
    assert.ok(m, `title ${d.id} in the DB`);
    assert.deepEqual([m.classId, m.ribbon, m.ensign, m.medal, m.masterMedal, m.rank, m.slot, m.req1, m.req2], [d.classId, d.ribbon, d.ensign, d.medal, d.master, d.rank, d.slot, d.req1, d.req2], `title ${d.id}`);
  }
});

// ---- packets ---------------------------------------------------------------------------------------------------------

test("titleInfoPackets: 2363 badges + 2383 titles decode with the client's own parsers", () => {
  const sent: Sent[] = [];
  const { a } = player(77, sent, { ribbon: 5, ensign: 4, medal: 3, masterMedal: 2 });
  a.title.flags = (1n << 1n) | (1n << 2n) | (1n << 40n);
  a.title.equiped1 = 2; a.title.equiped2 = 0; a.title.equiped3 = 40; a.title.slots = 3;
  const [medals, info] = titleInfoPackets(a);
  assert.equal(opOf(medals), 2363);
  assert.deepEqual(parseMedalInfo(new PacketReader(medals, 2)), { ribbon: 5, ensign: 4, medal: 3, master: 2 });
  assert.equal(opOf(info), 2383);
  assert.deepEqual(parseTitleInfo(new PacketReader(info, 2)), { flags: a.title.flags, equiped: [2, 0, 40], slots: 3 });
});

// ---- handlers --------------------------------------------------------------------------------------------------------

test("2376 get: needs the badges and the required title; takes the badges, sets the flag, answers 2377 (needs the DB)", async (t) => {
  if (!(await db(t))) return;
  const sent: Sent[] = [];
  const { a, c } = player(701, sent, { ribbon: 1 });
  await handleTitleChange(c, req(2)); // title 2 needs 2 ribbons and title 1
  assert.equal(u32(last(sent, 2377)!.bytes, 2), 0x80001083, "badges and required title missing");
  await handleTitleChange(c, req(1));
  const ok = last(sent, 2377)!;
  assert.equal(u32(ok.bytes, 2), 0, "title 1: 1 ribbon, rank 1");
  assert.equal(u32(ok.bytes, 6), 1, "slots");
  assert.equal(a.ribbon, 0, "the ribbon is spent");
  assert.ok((a.title.flags & (1n << 1n)) !== 0n);
  assert.deepEqual(parseMedalInfo(new PacketReader(last(sent, 2363)!.bytes, 2)), { ribbon: 0, ensign: 0, medal: 0, master: 0 });
  await handleTitleChange(c, req(1));
  assert.equal(u32(last(sent, 2377)!.bytes, 2), 0x80001083, "owned already");
  await handleTitleChange(c, req(0));
  assert.equal(u32(last(sent, 2377)!.bytes, 2), 0x80001083, "id 0 is no title");
  const before = sent.length;
  await handleTitleChange(c, req(45));
  assert.equal(sent.length, before, "id >= 45 is ignored");
});

test("2376 get: rank gate and chain (title 2 after title 1 with 2 ribbons) (needs the DB)", async (t) => {
  if (!(await db(t))) return;
  const sent: Sent[] = [];
  const { a, c } = player(702, sent, { ribbon: 3, rank: 5 });
  await handleTitleChange(c, req(1));
  await handleTitleChange(c, req(2));
  assert.equal(u32(last(sent, 2377)!.bytes, 2), 0, "title 2 once title 1 is owned");
  assert.equal(a.ribbon, 0);
  const low = player(703, sent, { ribbon: 9, rank: 0 });
  await handleTitleChange(low.c, req(1));
  assert.equal(u32(last(sent, 2377)!.bytes, 2), 0x80001083, "rank 0 < rank 1");
  assert.equal(low.a.ribbon, 9, "nothing taken from a refused get");
});

test("2378 equip / 2380 release: owned only, one per class, one slot per title (needs the DB)", async (t) => {
  if (!(await db(t))) return;
  const sent: Sent[] = [];
  const { a, c } = player(704, sent, { ribbon: 3, rank: 5 });
  await handleTitleChange(c, req(1));
  await handleTitleChange(c, req(2));
  await handleTitleEquip(c, req(0, 3));
  assert.equal(u32(last(sent, 2379)!.bytes, 2), 0x80000000, "not owned");
  await handleTitleEquip(c, req(0, 1));
  const ok = last(sent, 2379)!;
  assert.equal(u32(ok.bytes, 2), 0);
  assert.deepEqual([ok.bytes[6], ok.bytes[7]], [0, 1], "slot 0, title 1");
  assert.equal(a.title.equiped1, 1);
  await handleTitleEquip(c, req(1, 1));
  assert.equal(u32(last(sent, 2379)!.bytes, 2), 0x80000000, "the same title in two slots");
  await handleTitleEquip(c, req(1, 2));
  assert.equal(u32(last(sent, 2379)!.bytes, 2), 0x80000000, "titles 1 and 2 are the same class");
  await handleTitleEquip(c, req(3, 2));
  assert.equal(u32(last(sent, 2379)!.bytes, 2), 0x80000000, "slot 3 does not exist");
  await handleTitleRelease(c, req(0, 2));
  assert.equal(u32(last(sent, 2381)!.bytes, 2), 0x80000000, "the title in slot 0 is not 2");
  await handleTitleRelease(c, req(0, 1));
  assert.equal(u32(last(sent, 2381)!.bytes, 2), 0);
  assert.equal(a.title.equiped1, 0);
});

// ---- the client's copy of the rules ----------------------------------------------------------------------------------

test("titleLogic getBlock agrees with handleTitleChange for the titles without awards (1..7) (needs the DB)", async (t) => {
  if (!(await db(t))) return;
  let pid = 800;
  for (const d of TITLES.filter((x) => x.id <= 7)) {
    const variants: [string, Partial<Badges> & { rank: number }, boolean][] = [
      ["exact cost", { ribbon: d.ribbon, ensign: d.ensign, medal: d.medal, masterMedal: d.master, rank: d.rank }, true],
      ["one badge short", { ribbon: Math.max(0, d.ribbon - 1), ensign: Math.max(0, d.ensign - 1), medal: d.medal, masterMedal: d.master, rank: d.rank }, false],
      ["rank short", { ribbon: d.ribbon, ensign: d.ensign, medal: d.medal, masterMedal: d.master, rank: d.rank - 1 }, false],
    ];
    for (const [name, o, wantOk] of variants) {
      if (!wantOk && o.rank === d.rank && !d.ribbon && !d.ensign) continue; // nothing to be short of
      if (!wantOk && o.rank < 0) continue;
      for (const withReq of d.req1 || d.req2 ? [true, false] : [true]) {
        const sent: Sent[] = [];
        const { a, c } = player(pid++, sent, o);
        if (withReq) for (const r of [d.req1, d.req2]) if (r) a.title.flags |= 1n << BigInt(r);
        const state: TitleState = { ...emptyTitleState(), flags: a.title.flags, ribbon: a.ribbon, ensign: a.ensign, medal: a.medal, master: a.masterMedal, known: true };
        const block = getBlock(state, a.rank, d);
        await handleTitleChange(c, req(d.id));
        const accepted = u32(last(sent, 2377)!.bytes, 2) === 0;
        assert.equal(block === null, accepted, `title ${d.id}: ${name}${withReq ? "" : ", requirement missing"}`);
        assert.equal(accepted, wantOk && withReq, `title ${d.id}: ${name}${withReq ? "" : ", requirement missing"} (expected)`);
      }
    }
  }
});

test("titleLogic equipBlock: locked slot, owned, same title, same class", () => {
  const owned = (...ids: number[]): TitleState => ({ ...emptyTitleState(), flags: ids.reduce((f, i) => f | (1n << BigInt(i)), 0n), slots: 2, known: true });
  const s = owned(1, 2, 8);
  assert.equal(equipBlock(s, 1, 2), "locked", "slot 3 needs slots >= 3");
  assert.equal(equipBlock(s, 5, 0), "notOwned");
  assert.equal(equipBlock(s, 1, 0), null);
  assert.equal(equipBlock({ ...s, equiped: [1, 0, 0] }, 1, 1), "already");
  assert.equal(equipBlock({ ...s, equiped: [1, 0, 0] }, 2, 1), "sameClass", "titles 1 and 2 are both class 1");
  assert.equal(equipBlock({ ...s, equiped: [1, 0, 0] }, 8, 1), null, "title 8 is class 2");
  assert.ok(hasTitle(s, 8) && !hasTitle(s, 3));
});
